/**
 * Issues a signed offline licence file (Part 9.9). Reads dev-private-key.pem
 * (generated by generate-keypair.js) and signs a canonical JSON payload.
 *
 * Usage: node issue-licence.js <orgName> <edition> <maxDevices> <supportTermEndISO>
 * Example: node issue-licence.js "Sai Life Sciences" team 40 2027-11-07
 */
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const [orgName, edition, maxDevicesStr, supportTermEnd] = process.argv.slice(2);
if (!orgName || !edition || !maxDevicesStr || !supportTermEnd) {
  console.error('Usage: node issue-licence.js <orgName> <edition> <maxDevices> <supportTermEndISO>');
  process.exit(1);
}

const privateKeyPath = path.join(__dirname, 'dev-private-key.pem');
if (!fs.existsSync(privateKeyPath)) {
  console.error('dev-private-key.pem not found -- run generate-keypair.js first.');
  process.exit(1);
}
const privateKey = fs.readFileSync(privateKeyPath, 'utf8');

const payload = {
  organisation: orgName,
  edition,
  maxDevices: parseInt(maxDevicesStr, 10),
  supportTermEnd,
  featureFlags: {},
  issuedAt: new Date().toISOString(),
};

const canonical = JSON.stringify(payload);
const signature = crypto.sign('sha256', Buffer.from(canonical), {
  key: privateKey,
  padding: crypto.constants.RSA_PKCS1_PSS_PADDING,
});

const licence = { payload, signature: signature.toString('base64') };
const outPath = path.join(__dirname, 'licence.json');
fs.writeFileSync(outPath, JSON.stringify(licence, null, 2));
console.log('Wrote', outPath);
